#include "json.h"
namespace rc { namespace { struct Parser { std::wstring_view s; size_t i{}; std::wstring err; void ws(){while(i<s.size()&&iswspace(s[i]))++i;} bool lit(std::wstring_view x){if(s.substr(i,x.size())!=x)return false;i+=x.size();return true;} Json val(){ws();if(i>=s.size()){err=L"JSON が途中で終了しました";return{};} wchar_t c=s[i];if(c==L'{')return obj();if(c==L'[')return arr();if(c==L'\"')return str();if(c==L't'||c==L'f'){Json r;r.type=Json::Type::Bool;r.boolean=lit(L"true");if(!r.boolean&&!lit(L"false"))err=L"不正な真偽値";return r;}if(c==L'n'){if(!lit(L"null"))err=L"不正な null";return{};}return num();} Json str(){Json r;r.type=Json::Type::String;++i;while(i<s.size()){wchar_t c=s[i++];if(c==L'\"')return r;if(c==L'\\'){if(i==s.size()){err=L"不正なエスケープ";return{};}c=s[i++];if(c==L'n')r.string+=L'\n';else if(c==L'r')r.string+=L'\r';else if(c==L't')r.string+=L'\t';else if(c==L'\"'||c==L'\\'||c==L'/')r.string+=c;else {err=L"未対応のJSONエスケープ";return{};}}else r.string+=c;}err=L"文字列が閉じられていません";return{};} Json num(){size_t p=i;while(i<s.size()&&wcschr(L"-+.0123456789eE",s[i]))++i;try{Json r;r.type=Json::Type::Number;r.number=std::stod(std::wstring(s.substr(p,i-p)));return r;}catch(...){err=L"不正な数値";return{};}} Json arr(){Json r;r.type=Json::Type::Array;++i;ws();if(i<s.size()&&s[i]==L']'){++i;return r;}for(;;){r.array.push_back(val());if(!err.empty())return{};ws();if(i>=s.size()|| (s[i]!=L','&&s[i]!=L']')){err=L"配列の区切りが不正です";return{};}if(s[i++]==L']')return r;}} Json obj(){Json r;r.type=Json::Type::Object;++i;ws();if(i<s.size()&&s[i]==L'}'){++i;return r;}for(;;){ws();if(i>=s.size()||s[i]!=L'\"'){err=L"オブジェクトのキーが不正です";return{};}auto k=str();ws();if(i>=s.size()||s[i++]!=L':'){err=L"コロンがありません";return{};}r.object.emplace(k.string,val());if(!err.empty())return{};ws();if(i>=s.size()||(s[i]!=L','&&s[i]!=L'}')){err=L"オブジェクトの区切りが不正です";return{};}if(s[i++]==L'}')return r;}} }; std::wstring esc(const std::wstring& s){std::wstring r=L"\"";for(auto c:s){if(c==L'\"'||c==L'\\')r+=L'\\';if(c==L'\n')r+=L"\\n";else if(c==L'\r')r+=L"\\r";else if(c==L'\t')r+=L"\\t";else r+=c;}return r+L"\"";} }
std::optional<Json> Json::Parse(std::wstring_view s,std::wstring* error){Parser p{s};auto r=p.val();p.ws();if(p.err.empty()&&p.i!=s.size())p.err=L"JSON の末尾が不正です";if(!p.err.empty()){if(error)*error=p.err;return{};}return r;} const Json* Json::Find(std::wstring_view k)const{auto it=object.find(k);return it==object.end()?nullptr:&it->second;} std::wstring Json::Dump()const{switch(type){case Type::Null:return L"null";case Type::Bool:return boolean?L"true":L"false";case Type::Number:return std::to_wstring(number);case Type::String:return esc(string);case Type::Array:{std::wstring r=L"[";for(size_t i=0;i<array.size();++i){if(i)r+=L",";r+=array[i].Dump();}return r+L"]";}case Type::Object:{std::wstring r=L"{";bool first=true;for(auto&[k,v]:object){if(!first)r+=L",";first=false;r+=esc(k)+L":"+v.Dump();}return r+L"}";}}return{};}}
